```sop
@slots literal
{"groups": [{"name": "A", "seats": 5}, {"name": "B", "seats": 3}, {"name": "C", "seats": 3}], "threshold": 6}

@answer jsEval
function combinations(arr) {
  const result = [];
  const n = arr.length;
  for (let mask = 1; mask < (1 << n); mask++) {
    const subset = [];
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) subset.push(arr[i]);
    }
    result.push(subset);
  }
  return result;
}
const groups = $slots.groups;
const threshold = $slots.threshold;
const subsets = combinations(groups);
const winning = subsets.filter((subset) => subset.reduce((sum, g) => sum + g.seats, 0) >= threshold);
const minimalWinning = winning.filter((subset) => {
  if (subset.length === 1) return true;
  return subset.every((member) => {
    const without = subset.filter((g) => g !== member);
    const sum = without.reduce((s, g) => s + g.seats, 0);
    return sum < threshold;
  });
});
if (minimalWinning.length === 0) {
  return 'No coalition is minimal winning.';
}
const names = minimalWinning.map((subset) => '{' + subset.map((g) => g.name).join(',') + '}');
return 'The minimal winning coalitions are ' + names.join(', ') + '.';
```

